typedef struct Node { int data; struct Node *link; } Node;
int FindKthFromEnd(Node *head, int k) {
    if (head == NULL || k <= 0) return 0;
    Node *fast = head, *slow = head; // head 为哨兵头结点
    for (int i = 0; i < k; ++i) {
        fast = fast->link;
        if (fast == NULL) return 0;
    }
    while (fast->link != NULL) {
        fast = fast->link;
        slow = slow->link;
    }
    printf("%d\n", slow->data);
    return 1;
}

void reverse(int a[], int left, int right) {
    while (left < right) {
        int t = a[left]; a[left] = a[right]; a[right] = t;
        ++left; --right;
    }
}
void rotateLeft(int a[], int n, int p) {
    if (a == NULL || n <= 1) return;
    p %= n;
    if (p < 0) p += n;
    reverse(a, 0, p - 1);
    reverse(a, p, n - 1);
    reverse(a, 0, n - 1);
}
